/* HARDGATE — build stamp. Single source of truth for "which version am I running?"
   Loaded FIRST so every later script can read G.HG_BUILD. */
(function(){
'use strict';
var G = (typeof window !== 'undefined') ? window : globalThis;

var HG_BUILD = {
  version: 'hg-v937',
  pack: 'MILLI GOLD BACKTESTED AND FORWARD-TESTED - THE ROSTER BEATS THE DESK UNANIMOUSLY AND STILL LOSES. hg-v936 shipped a roster chosen on the WHOLE walk, disclosed that honestly, and then led the tab with that rosters IN-SAMPLE figure anyway, calling it an upper bound. This pack measured the bound. IT IS NEGATIVE. THE BACKTEST, as a book someone could actually run. All at once the roster reads +0.0643R and +0.0527R at the two fill bounds against a desk at -0.1160R and -0.2864R; ONE POSITION AT A TIME - the hg-v918/v926 read, since this walk publishes 61.8 plans a day and holds dozens at once - it reads +0.0153R at both bounds against the desks -0.0226R and -0.3744R. Every one of those is IN SAMPLE, on the walk the roster was chosen from, and that is precisely why the next measurement had to be run instead of quoted. THE FORWARD TEST, which is the one that decides. The roster is rebuilt on the EARLIER part of the walk only and judged on the part that came after - what a reader actually does: pick the mechanics that have paid so far, trade them next. Three anchored splits at 50/60/70 percent, both fill bounds, six trials, reported separately and never averaged because they share a test tail. RESULT: the rule beats the full OMNIGOLD book in 6 OF 6 TRIALS, UNANIMOUSLY, and is net-positive in 0 OF 6. Forward net runs -0.1673R to -0.0390R against a desk running -0.1160R to -0.2864R. So SELECTING THE MECHANICS THAT HAVE PAID IS MEASURABLY BETTER THAN NOT SELECTING, AND STILL LOSES MONEY ON EVERY SLICE THAT CAME AFTER THE CHOICE WAS MADE. Beating the desk and paying are tracked as SEPARATE claims throughout, because the entire finding is that one happened and the other did not. AND THE SIZE OF THE SELECTION BIAS IS NOW NAMED: only 6 to 7 of the 9 shipped mechanics are re-chosen when the rule cannot see the whole walk, so the rest are artefacts of having seen it. The shipped roster scores +0.0939R, +0.0373R and +0.0171R on those same test tails - and it is CONTAMINATED there by construction, having been chosen on the whole walk including the tails. It is printed beside the honest number and marked, and the verdict is computed from the re-learned roster only; the guard asserts the verdict expression never reads the contaminated one. THE TAB NOW LEADS WITH THE FORWARD RESULT instead of the in-sample figure, names that figure as the one to distrust, and with no forward result baked it REFUSES to quote it on its own - because a number measured optimistic by more than its own size is worse than no number. HG_MILLI_FORWARD is generated from the replay by scripts/milli-gold-walk.mjs (the hg-v921 rule), round-trips to zero drift, and npm run gold:milli-walk is the read-only check. One design fix the mutation pass forced: the verdict was inline, and because all six real trials agree, swapping EVERY for SOME changed nothing observable and survived - a rule that would have accepted ONE agreeing split, which is the failure hg-v920 exists to prevent. It is now an exported function exercised on MIXED trials. Tests: tests/test-milli-gold-walk.mjs (77 assertions) - which proves the no-leak property behaviourally with a mechanic that pays only in the tail, plus the mirror showing it WOULD be admitted if trained on everything - and tests/test-milli-gold.mjs (200 assertions), rebased onto the new headline. 11 of 11 mutations caught. No threshold moves, no gate loosens, and the roster itself is UNCHANGED: this pack measured what was already shipped and corrected what the tab claims about it. Suite: 591 files, 0 failed',
  built: '2026-09-23T00:00:00Z'
};

function hgBuildLabel(b){
  b = b || HG_BUILD;
  var v = String(b.version || '').replace(/^hg-/, '');
  var p = b.pack ? ' · ' + b.pack : '';
  return v ? v + p : 'unknown build';
}

function hgBuildParseVersion(text){
  try{
    if (typeof text !== 'string' || !text) return null;
    var m = text.match(/version\s*:\s*['"]([A-Za-z0-9._-]{1,64})['"]/);
    return m ? m[1] : null;
  }catch(e){ return null; }
}

function hgBuildCompare(loaded, live){
  if (!loaded || !live) return { state: 'unknown', reason: 'could not read one side' };
  if (String(loaded) === String(live)) return { state: 'fresh', reason: 'matches server' };
  return { state: 'stale', reason: 'server is on ' + live + ', this tab loaded ' + loaded };
}

function hgBuildDistance(loaded, live){
  try{
    var a = String(loaded || '').match(/(\d+)\s*$/);
    var b = String(live || '').match(/(\d+)\s*$/);
    if (!a || !b) return null;
    return (+b[1]) - (+a[1]);
  }catch(e){ return null; }
}

function hgBuildChipState(res, b){
  b = b || HG_BUILD;
  var label = hgBuildLabel(b);
  if (!res || res.state === 'pending') return { text: label, cls: 'ok', title: 'checking for newer build' };
  if (res.state === 'fresh') return { text: label, cls: 'ok', title: 'running current build (' + res.live + ')' };
  if (res.state === 'stale'){
    var d = hgBuildDistance(res.loaded, res.live);
    var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
    return { text: label + ' · STALE' + behind, cls: 'bad', title: res.reason + ' — hard-reload to pick it up' };
  }
  return { text: label + ' · ?', cls: 'warn', title: (res.reason || 'freshness unknown') + ' — offline or blocked' };
}

function hgBuildFreshness(fetchImpl){
  var f = (typeof fetchImpl === 'function') ? fetchImpl : (typeof G.fetch === 'function' ? G.fetch.bind(G) : null);
  var loaded = HG_BUILD.version;
  if (!f) return Promise.resolve({ state: 'unknown', loaded: loaded, live: null, reason: 'no fetch' });
  var url = './build-stamp.js?fresh=' + Date.now();
  return f(url, { cache: 'no-store' }).then(function(res){
    if (!res || !res.ok) throw new Error('http ' + (res && res.status));
    return res.text();
  }).then(function(text){
    var live = hgBuildParseVersion(text);
    var cmp = hgBuildCompare(loaded, live);
    return { state: cmp.state, loaded: loaded, live: live, reason: cmp.reason };
  }).catch(function(e){
    return { state: 'unknown', loaded: loaded, live: null, reason: (e && e.message) || 'network failed' };
  });
}

function hgBuildSwWaiting(){
  try{
    var sw = G.navigator && G.navigator.serviceWorker;
    if (!sw || !sw.controller) return Promise.resolve(false);
    return sw.getRegistration().then(function(reg){
      return !!(reg && reg.waiting);
    }).catch(function(){ return false; });
  }catch(e){ return Promise.resolve(false); }
}

function hgRenderBuildChip(el, res){
  try{
    var node = el || (G.document && G.document.getElementById('chipBuild'));
    if (!node) return null;
    var st = hgBuildChipState(res);
    node.textContent = '';
    var b = G.document.createElement('b');
    b.textContent = st.text;
    node.appendChild(b);
    node.title = st.title;
    node.className = 'statuschip hg-build-' + st.cls;
    return st;
  }catch(e){ return null; }
}

function hgRenderVerBadge(res){
  try{
    var node = G.document && G.document.getElementById('hgVerBadge');
    if (!node) return null;
    var v = String(HG_BUILD.version || '').replace(/^hg-/, '');
    if (!v){ node.style.display = 'none'; return null; }
    if (res && res.state === 'stale'){
      var d = hgBuildDistance(res.loaded, res.live);
      var behind = (d != null && d > 0) ? ' (' + d + ' behind)' : '';
      node.textContent = v + ' · STALE' + behind;
      node.className = 'verbadge verbadge-stale';
      node.title = (res.reason || 'stale') + ' — reloading…';
      return { stale: true };
    }
    node.textContent = v;
    node.className = 'verbadge';
    node.title = HG_BUILD.version + (HG_BUILD.pack ? (' · ' + HG_BUILD.pack) : '');
    return { stale: false };
  }catch(e){ return null; }
}

function hgBuildMaybeReload(res, storage, reloadFn){
  try{
    if (!res || res.state !== 'stale' || !res.live) return false;
    var store = storage;
    if (!store && G.sessionStorage) store = G.sessionStorage;
    if (!store || typeof store.getItem !== 'function') return false;
    var key = 'hg_build_reload_' + String(res.live);
    if (store.getItem(key)) return false;
    var reload = reloadFn;
    if (!reload && G.location && typeof G.location.reload === 'function') reload = G.location.reload.bind(G.location);
    if (typeof reload !== 'function') return false;
    store.setItem(key, '1');
    reload();
    return true;
  }catch(e){}
  return false;
}

function hgBuildApplyFreshness(res){
  try{
    if (!res) return res;
    hgRenderBuildChip(null, res);
    hgRenderVerBadge(res);
    G.HG_BUILD_FRESHNESS = res;
    hgBuildMaybeReload(res);
    return res;
  }catch(e){ return res; }
}

function hgBuildInit(){
  try{
    hgRenderBuildChip(null, null);
    hgRenderVerBadge(null);
    hgBuildFreshness().then(function(res){
      return hgBuildSwWaiting().then(function(waiting){
        if (waiting && res.state === 'fresh'){
          res = { state: 'stale', loaded: res.loaded, live: res.live, reason: 'new build downloaded' };
        }
        return hgBuildApplyFreshness(res);
      });
    });
    if (G.document && typeof G.document.addEventListener === 'function'){
      G.document.addEventListener('visibilitychange', function(){
        try{
          if (!G.document || G.document.visibilityState !== 'visible') return;
          hgBuildFreshness().then(hgBuildApplyFreshness);
        }catch(e){}
      });
    }
  }catch(e){}
}

G.HG_BUILD = HG_BUILD;
G.hgBuildLabel = hgBuildLabel;
G.hgBuildParseVersion = hgBuildParseVersion;
G.hgBuildCompare = hgBuildCompare;
G.hgBuildDistance = hgBuildDistance;
G.hgBuildChipState = hgBuildChipState;
G.hgBuildFreshness = hgBuildFreshness;
G.hgBuildSwWaiting = hgBuildSwWaiting;
G.hgRenderBuildChip = hgRenderBuildChip;
G.hgRenderVerBadge = hgRenderVerBadge;
G.hgBuildMaybeReload = hgBuildMaybeReload;
G.hgBuildApplyFreshness = hgBuildApplyFreshness;
G.hgBuildInit = hgBuildInit;

try{
  if (G.document){
    if (G.document.readyState === 'loading'){
      G.document.addEventListener('DOMContentLoaded', hgBuildInit);
    } else {
      hgBuildInit();
    }
  }
}catch(e){}

})();
